async ({ workspace: { read, edit } }) => {
  const f: any = await read("docs/extensions.md", { format: "raw" });
  let c: string = f.content;
  const start = c.indexOf("### Images\n\n");
  const endMarker = "\n\npi-durable extensions run in the process of pi-action. Thus,";
  const end = c.indexOf(endMarker, start);
  const block = c.slice(start, end);
  c = c.slice(0, start) + c.slice(end + 2);
  const anchor = "### Show tool calls in the workflow log";
  c = c.replace(anchor, block + "\n\n" + anchor);
  await edit("docs/extensions.md", { revision: f.revision, changes: [{ kind: "replaceFile", content: c }] });
  const s = c.indexOf("### Host options");
  return c.slice(s, s + 2600);
}
